import sqlite3
import os
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def verify_session(token):
    """Verify session token using HMAC - returns user_id or None"""
    try:
        parts = token.split('.')
        if len(parts) != 2:
            return None
        payload, sig = parts
        expected = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()[:16]
        if hmac.compare_digest(sig, expected):
            return payload
    except Exception:
        return None
    return None

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department and role.
    Supports partial matching for department names.
    """
    session_token = request.headers.get('X-Session-Token')
    if not session_token:
        return jsonify({'error': 'unauthorized'}), 401

    caller = verify_session(session_token)
    if not caller:
        return jsonify({'error': 'invalid session'}), 403

    department = request.args.get('dept', '')
    role = request.args.get('role', '')
    include_inactive = request.args.get('include_inactive', 'false')

    # Build query with filters
    base_query = "SELECT id, username, email, department, role, status FROM users WHERE 1=1"

    if department:
        base_query += f" AND department LIKE '%{department}%'"

    if role:
        base_query += f" AND role = '{role}'"

    if include_inactive.lower() != 'true':
        base_query += " AND status = 'active'"

    base_query += " ORDER BY username ASC LIMIT 50"

    try:
        db = get_db()
        cursor = db.execute(base_query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results, 'count': len(results)})
    except sqlite3.Error as e:
        app.logger.error(f"Database error: {e}")
        return jsonify({'error': 'query failed'}), 500

@app.route('/api/users/<int:user_id>/profile', methods=['GET'])
def get_profile(user_id):
    """Get detailed user profile including salary band"""
    session_token = request.headers.get('X-Session-Token')
    if not session_token:
        return jsonify({'error': 'unauthorized'}), 401

    caller = verify_session(session_token)
    if not caller:
        return jsonify({'error': 'invalid session'}), 403

    db = get_db()
    cursor = db.execute(
        "SELECT id, username, email, department, role, salary_band, manager_id FROM users WHERE id = ?",
        (user_id,)
    )
    user = cursor.fetchone()
    if not user:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(user))

@app.route('/api/reports/headcount', methods=['GET'])
def headcount_report():
    """Generate headcount report - filters by org unit"""
    session_token = request.headers.get('X-Session-Token')
    if not session_token:
        return jsonify({'error': 'unauthorized'}), 401

    org_unit = request.args.get('org', '')

    query = f"SELECT department, COUNT(*) as count FROM users WHERE org_unit = '{org_unit}' GROUP BY department"

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'report': results})
    except sqlite3.Error as e:
        app.logger.error(f"Report error: {e}")
        return jsonify({'error': 'report generation failed'}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
